1	import { App, normalizePath } from 'obsidian';
2	import { ComponentEntry } from './componentScanner';
3	
4	export class ComponentManager {
5	  /**
6	   * Sanitizes a ComponentEntry to strictly conform to the clean V2 schema,
7	   * removing any obsolete legacy keys (keywords, require, negate, exclude, inherit, etc.).
8	   */
9	  public static sanitizeEntry(raw: any): ComponentEntry {
10	    const clean: ComponentEntry = {
11	      display_name: raw.display_name || '',
12	      prompt: raw.prompt || '',
13	    };
14	
15	    if (raw.image && typeof raw.image === 'string' && raw.image.trim()) {
16	      clean.image = raw.image.trim();
17	    }
18	
19	    if (Array.isArray(raw.tag_team) && raw.tag_team.length > 0) {
20	      clean.tag_team = raw.tag_team.filter(Boolean);
21	    }
22	
23	    const antiPrompt =
24	      typeof raw['anti-prompt'] === 'string'
25	        ? raw['anti-prompt'].trim()
26	        : Array.isArray(raw.exclude)
27	        ? raw.exclude.join(', ').trim()
28	        : '';
29	    if (antiPrompt) {
30	      clean['anti-prompt'] = antiPrompt;
31	    }
32	
33	    const requirements = Array.isArray(raw.requirement)
34	      ? raw.requirement.filter(Boolean)
35	      : Array.isArray(raw.require)
36	      ? raw.require.filter(Boolean)
37	      : [];
38	    if (requirements.length > 0) {
39	      clean.requirement = requirements;
40	    }
41	
42	    const impacts = Array.isArray(raw.impact)
43	      ? raw.impact.filter(Boolean)
44	      : Array.isArray(raw.keywords)
45	      ? raw.keywords.filter(Boolean)
46	      : [];
47	    if (impacts.length > 0) {
48	      clean.impact = impacts;
49	    }
50	
51	    if (raw.completed === true) {
52	      clean.completed = true;
53	    }
54	
55	    if (Array.isArray(raw.subjects) && raw.subjects.length >= 2) {
56	      clean.subjects = [Number(raw.subjects[0]) || 0, Number(raw.subjects[1]) || 0];
57	    }
58	
59	    if (raw.description && typeof raw.description === 'string' && raw.description.trim()) {
60	      clean.description = raw.description.trim();
61	    }
62	
63	    return clean;
64	  }
65	
66	  /**
67	   * Resolves the full vault path for a given component file relative path.
68	   */
69	  public static resolveFullPath(relPath: string): string {
70	    const clean = normalizePath(relPath).replace(/\\/g, '/');
71	    if (clean.startsWith('Hazard_Trigger_Data/')) {
72	      return clean;
73	    }
74	    if (clean.startsWith('Matrices/')) {
75	      return normalizePath(`Hazard_Trigger_Data/${clean}`).replace(/\\/g, '/');
76	    }
77	    return normalizePath(`Hazard_Trigger_Data/Components/${clean}`).replace(/\\/g, '/');
78	  }
79	
80	  /**
81	   * Overwrites the entire JSON file with the full set of sanitized entries (batch table commit).
82	   */
83	  public static async saveAllFileEntries(
84	    app: App,
85	    fileRelPath: string,
86	    entries: Record<string, ComponentEntry>
87	  ): Promise<boolean> {
88	    const adapter = app.vault.adapter;
89	    const targetPath = this.resolveFullPath(fileRelPath);
90	
91	    try {
92	      // Ensure parent directory exists
93	      const lastSlash = targetPath.lastIndexOf('/');
94	      if (lastSlash > 0) {
95	        const parentDir = targetPath.substring(0, lastSlash);
96	        if (!(await adapter.exists(parentDir))) {
97	          await adapter.mkdir(parentDir);
98	        }
99	      }
100	
101	      // Sanitize all entries to pristine clean schema
102	      const sanitizedEntries: Record<string, ComponentEntry> = {};
103	      Object.entries(entries).forEach(([k, v]) => {
104	        sanitizedEntries[k] = this.sanitizeEntry(v);
105	      });
106	
107	      await adapter.write(targetPath, JSON.stringify(sanitizedEntries, null, 2));
108	      return true;
109	    } catch (err) {
110	      console.error(`[ComponentManager] Failed to write file ${targetPath}:`, err);
111	      return false;
112	    }
113	  }
114	
115	  /**
116	   * Saves, creates, or updates a single component option entry in a JSON file.
117	   * If oldKey is provided and different from newKey, oldKey will be removed (rename support).
118	   */
119	  public static async saveEntry(
120	    app: App,
121	    fileRelPath: string,
122	    newKey: string,
123	    entryData: ComponentEntry,
124	    oldKey?: string
125	  ): Promise<boolean> {
126	    const adapter = app.vault.adapter;
127	    const targetPath = this.resolveFullPath(fileRelPath);
128	
129	    try {
130	      let existingEntries: Record<string, ComponentEntry> = {};
131	
132	      if (await adapter.exists(targetPath)) {
133	        const raw = await adapter.read(targetPath);
134	        existingEntries = JSON.parse(raw);
135	      }
136	
137	      // If renaming, remove old key
138	      if (oldKey && oldKey !== newKey && existingEntries[oldKey] !== undefined) {
139	        delete existingEntries[oldKey];
140	      }
141	
142	      // Sanitize and set new entry
143	      existingEntries[newKey] = this.sanitizeEntry(entryData);
144	
145	      // Sanitize all other existing entries as well
146	      const sanitizedEntries: Record<string, ComponentEntry> = {};
147	      Object.entries(existingEntries).forEach(([k, v]) => {
148	        sanitizedEntries[k] = this.sanitizeEntry(v);
149	      });
150	
151	      // Write back formatted JSON
152	      await adapter.write(targetPath, JSON.stringify(sanitizedEntries, null, 2));
153	      return true;
154	    } catch (err) {
155	      console.error(`[ComponentManager] Failed to save entry to ${targetPath}:`, err);
156	      return false;
157	    }
158	  }
159	
160	  /**
161	   * Deletes a component option entry from a JSON file.
162	   */
163	  public static async deleteEntry(
164	    app: App,
165	    fileRelPath: string,
166	    keyToDelete: string
167	  ): Promise<boolean> {
168	    const adapter = app.vault.adapter;
169	    const targetPath = this.resolveFullPath(fileRelPath);
170	
171	    try {
172	      if (!(await adapter.exists(targetPath))) return false;
173	
174	      const raw = await adapter.read(targetPath);
175	      const existingEntries: Record<string, ComponentEntry> = JSON.parse(raw);
176	
177	      if (existingEntries[keyToDelete] !== undefined) {
178	        delete existingEntries[keyToDelete];
179	        await adapter.write(targetPath, JSON.stringify(existingEntries, null, 2));
180	        return true;
181	      }
182	      return false;
183	    } catch (err) {
184	      console.error(`[ComponentManager] Failed to delete entry from ${targetPath}:`, err);
185	      return false;
186	    }
187	  }
188	
189	  /**
190	   * Creates a brand new component JSON file.
191	   */
192	  public static async createComponentFile(
193	    app: App,
194	    folderRelPath: string,
195	    fileName: string,
196	    displayName?: string
197	  ): Promise<string | null> {
198	    const adapter = app.vault.adapter;
199	    const sanitizedFileName = fileName.endsWith('.json') ? fileName : `${fileName}.json`;
200	    const folderPath = this.resolveFullPath(folderRelPath);
201	    const targetFilePath = normalizePath(`${folderPath}/${sanitizedFileName}`).replace(/\\/g, '/');
202	
203	    try {
204	      if (!(await adapter.exists(folderPath))) {
205	        await adapter.mkdir(folderPath);
206	      }
207	
208	      if (await adapter.exists(targetFilePath)) {
209	        return targetFilePath; // Already exists
210	      }
211	
212	      // Write initial empty entries JSON
213	      await adapter.write(targetFilePath, JSON.stringify({}, null, 2));
214	      return targetFilePath;
215	    } catch (err) {
216	      console.error(`[ComponentManager] Failed to create file at ${targetFilePath}:`, err);
217	      return null;
218	    }
219	  }
220	}
