195	function calculateState(
196	  folders: ComponentFolderNode[],
197	  matrixDomains: MatrixDomainNode[],
198	  selections: Record<string, string | null>,
199	  randomPools: Record<string, string[]> = {},
200	  matrixBaseStates: Record<string, string[]> = {},
201	  matrixUnlockedPools: Record<string, string[]> = {},
202	  unlockLockedAll: boolean = false,
203	  unlockKeys: string[] = [],
204	  unlockedOptionKeys: string[] = [],
205	  globalLockedKeys: Record<string, boolean> = {},
206	  lockedRandomSelections: Record<string, string> = {},
207	  conditions: Record<string, ConditionEntry> = {},
208	  ignoredConditionIds: string[] = []
209	) {
210	  let totalFemales = 0;
211	  let totalMales = 0;
212	  let povDeltaFemales = 0;
213	  let povDeltaMales = 0;
214	  let isPOV = false;
215	
216	  const resolvedSelections: Record<string, string | null> = {};
217	  const activeEntries: { entry: ComponentEntry; fileRelPath: string }[] = [];
218	  const activeKeywordsSet = new Set<string>();
219	  const activeExclusionsSet = new Set<string>();
220	  let randomCount = 0;
221	
222	  const cleanUnlockKeys = (unlockKeys || []).map((k) => k.toLowerCase().trim());
223	  const cleanUnlockedOptionKeys = (unlockedOptionKeys || []).map((k) => k.toLowerCase().trim());
224	
225	  // Helper to gather all files across standalone folders and matrix domains
226	  const allFolderContainers: { displayName: string; relPath: string; files: ComponentFileNode[]; isMatrixDomain?: boolean; domain?: MatrixDomainNode }[] = [
227	    ...folders.map((f) => ({ displayName: f.displayName, relPath: f.relPath, files: f.files })),
228	    ...matrixDomains.map((d) => ({ displayName: d.displayName, relPath: d.relPath, files: d.files, isMatrixDomain: true, domain: d })),
229	  ];
230	
231	  // 1. Pass 1: Gather fixed (non-random) active selected entries to establish constraints
232	  for (const container of allFolderContainers) {
233	    for (const file of container.files) {
234	      const selectedKey = selections[file.relPath];
235	      if (selectedKey === RANDOM_SELECTION_KEY) {
236	        randomCount++;
237	        continue;
238	      }
239	
240	      if (selectedKey && file.entries[selectedKey]) {
241	        const entry = file.entries[selectedKey];
242	        resolvedSelections[file.relPath] = selectedKey;
243	        activeEntries.push({ entry, fileRelPath: file.relPath });
244	
245	        // Collect keywords & impacts
246	        const impacts = [
247	          ...(Array.isArray(entry.impact) ? entry.impact : []),
248	          ...(Array.isArray(entry.keywords) ? entry.keywords : []),
249	        ];
250	        impacts.forEach((k) => activeKeywordsSet.add(k.toLowerCase().trim()));
251	
252	        // Collect exclusions & anti-prompt
253	        const antiTokens = typeof entry['anti-prompt'] === 'string'
254	          ? entry['anti-prompt'].split(',').map((t) => t.trim()).filter(Boolean)
255	          : Array.isArray(entry.exclude)
256	          ? entry.exclude
257	          : [];
258	        antiTokens.forEach((e) => activeExclusionsSet.add(e.toLowerCase().trim()));
259	
260	        // Parse subjects vector: [females, males]
261	        if (Array.isArray(entry.subjects) && entry.subjects.length >= 2) {
262	          const [f, m] = entry.subjects;
263	          if (f < 0 || m < 0 || (entry.keywords && entry.keywords.includes('pov'))) {
264	            povDeltaFemales += f;
265	            povDeltaMales += m;
266	            isPOV = true;
267	          } else {
268	            totalFemales += f;
269	            totalMales += m;
270	          }
271	        }
272	      } else {
273	        resolvedSelections[file.relPath] = null;
274	      }
275	    }
276	  }
277	
278	  // Pre-Pass 2 Resolution: Compute Base Subject Cardinality & Context Keywords
279	  let visibleFemales = Math.max(0, totalFemales + povDeltaFemales);
280	  let visibleMales = Math.max(0, totalMales + povDeltaMales);
281	  let totalVisible = visibleFemales + visibleMales;
282	  let isSolo = totalVisible === 1;
283	
284	  if (isSolo) {
285	    activeKeywordsSet.add('solo');
286	    activeKeywordsSet.add('single_visible');
287	  } else if (totalVisible === 2) {
288	    activeKeywordsSet.add('duo_visible');
289	    activeKeywordsSet.add('multiple_visible');
290	  } else if (totalVisible >= 3) {
291	    activeKeywordsSet.add('group_visible');
292	    activeKeywordsSet.add('multiple_visible');
293	  }
294	
295	  if (isPOV) {
296	    activeKeywordsSet.add('pov');
297	  }
298	
299	  // Inject Base Anchor Keywords across all Matrix Domains
300	  for (const domain of matrixDomains) {
301	    const activeBaseIds = matrixBaseStates[domain.domainId] || [];
302	    for (const baseId of activeBaseIds) {
303	      activeKeywordsSet.add(baseId);
304	      activeKeywordsSet.add(`${domain.domainId}_base`);
305	    }
306	  }
307	
308	  // 2. Pass 2: Resolve random components dynamically honoring subset random pool, universal locked gacha exclusion, priority & active exclusions
309	  for (const container of allFolderContainers) {
310	    for (const file of container.files) {
311	      const selectedKey = selections[file.relPath];
312	      if (selectedKey !== RANDOM_SELECTION_KEY) continue;
313	
314	      const allOptionKeys = Object.keys(file.entries);
315	      if (allOptionKeys.length === 0) {
316	        resolvedSelections[file.relPath] = null;
317	        continue;
318	      }
319	
320	      // Check if user has defined a subset random pool for this file
321	      const customPool = randomPools[file.relPath];
322	      const baseCandidateKeys = Array.isArray(customPool)
323	        ? allOptionKeys.filter((k) => customPool.includes(k))
324	        : allOptionKeys;
325	
326	      // Filter out Locked / Niche options across all components unless unlocked by active template key
327	      const candidateKeys = baseCandidateKeys.filter((key) => {
328	        const entry = file.entries[key];
329	        const isLocked = Boolean(
330	          entry.locked ||
331	          entry.lock ||
332	          entry.is_locked ||
333	          globalLockedKeys[`${file.relPath}:${key}`] ||
334	          globalLockedKeys[key]
335	        );
336	
337	        if (!isLocked) return true;
338	
339	        // Check if unlocked by template metadata
340	        if (unlockLockedAll) return true;
341	        if (entry.lockKey && cleanUnlockKeys.includes(entry.lockKey.toLowerCase().trim())) return true;
342	        if (cleanUnlockedOptionKeys.includes(`${file.relPath}:${key}`.toLowerCase()) || cleanUnlockedOptionKeys.includes(key.toLowerCase())) return true;
343	
344	        // Locked out of gacha!
345	        return false;
346	      });
347	
348	      if (candidateKeys.length === 0) {
349	        // All options were deselected or locked out of gacha
350	        resolvedSelections[file.relPath] = null;
351	        continue;
352	      }
353	
354	      const activeKw = Array.from(activeKeywordsSet);
355	      const activeEx = Array.from(activeExclusionsSet);
356	
357	      const greenKeys: string[] = [];
358	      const blueKeys: string[] = [];
359	      const neutralKeys: string[] = [];
360	      const redKeys: string[] = [];
361	
362	      for (const key of candidateKeys) {
363	        const entry = file.entries[key];
364	        const keywords = [
365	          ...(Array.isArray(entry.impact) ? entry.impact : []),
366	          ...(Array.isArray(entry.keywords) ? entry.keywords : []),
367	        ].map((k) => k.toLowerCase().trim());
368	        const requires = [
369	          ...(Array.isArray(entry.requirement) ? entry.requirement : []),
370	          ...(Array.isArray(entry.require) ? entry.require : []),
371	        ].map((r) => r.toLowerCase().trim());
372	        const negates = (entry.negate || []).map((n) => n.toLowerCase().trim());
373	
374	        const isExcluded = keywords.some((k) => activeEx.includes(k));
375	        const isNegated = negates.some((n) => activeKw.includes(n));
376	
377	        if (isExcluded || isNegated) {
378	          redKeys.push(key);
379	          continue;
380	        }
381	
382	        if (requires.length === 0) {
383	          greenKeys.push(key);
384	          continue;
385	        }
386	
387	        const matchedReqs = requires.filter((r) => activeKw.includes(r)).length;
388	        if (matchedReqs === requires.length) {
389	          greenKeys.push(key);
390	        } else if (matchedReqs > 0) {
391	          blueKeys.push(key);
392	        } else {
393	          neutralKeys.push(key);
394	        }
395	      }
396	
397	      // Check if user has locked this specific random roll locally
398	      let chosenKey: string | null = null;
399	      const lockedRollKey = lockedRandomSelections[file.relPath];
400	      if (lockedRollKey && file.entries[lockedRollKey]) {
401	        chosenKey = lockedRollKey;
402	      } else {
403	        // Pick randomly from highest eligible tier pool among allowed candidate keys
404	        let pool = greenKeys;
405	        if (pool.length === 0) {
406	          pool = blueKeys.length > 0 ? blueKeys : neutralKeys;
407	        }
408	        if (pool.length === 0) {
409	          pool = candidateKeys.filter((k) => !redKeys.includes(k));
410	        }
411	        if (pool.length === 0) {
412	          pool = candidateKeys; // Fallback to candidate keys
413	        }
414	
415	        chosenKey = pool[Math.floor(Math.random() * pool.length)] || null;
416	      }
417	
418	      resolvedSelections[file.relPath] = chosenKey;
419	
420	      if (chosenKey && file.entries[chosenKey]) {
421	        const entry = file.entries[chosenKey];
422	        activeEntries.push({ entry, fileRelPath: file.relPath });
423	
424	        const impacts = [
425	          ...(Array.isArray(entry.impact) ? entry.impact : []),
426	          ...(Array.isArray(entry.keywords) ? entry.keywords : []),
427	        ];
428	        impacts.forEach((k) => activeKeywordsSet.add(k.toLowerCase().trim()));
429	
430	        const antiTokens = typeof entry['anti-prompt'] === 'string'
431	          ? entry['anti-prompt'].split(',').map((t) => t.trim()).filter(Boolean)
432	          : Array.isArray(entry.exclude)
433	          ? entry.exclude
434	          : [];
435	        antiTokens.forEach((e) => activeExclusionsSet.add(e.toLowerCase().trim()));
436	
437	        if (Array.isArray(entry.subjects) && entry.subjects.length >= 2) {
438	          const [f, m] = entry.subjects;
439	          if (f < 0 || m < 0 || (entry.keywords && entry.keywords.includes('pov'))) {
440	            povDeltaFemales += f;
441	            povDeltaMales += m;
442	            isPOV = true;
443	          } else {
444	            totalFemales += f;
445	            totalMales += m;
446	          }
447	        }
448	      }
449	    }
450	  }
451	
452	  // 3. Re-compute Visible Numbers with any dynamic additions
453	  visibleFemales = Math.max(0, totalFemales + povDeltaFemales);
454	  visibleMales = Math.max(0, totalMales + povDeltaMales);
455	  totalVisible = visibleFemales + visibleMales;
456	  isSolo = totalVisible === 1;
457	
458	  // 4. Condition Collision & Physics Engine
459	  const activeConditionIds = new Set<string>();
460	
461	  // Gather asserted conditions from active entries' impact and keywords
462	  console.log('[ConditionEngine] Active condition assertions:', Array.from(activeConditionIds).map((id) => conditions[id]?.display_name || id));
463	  activeEntries.forEach(({ entry, fileRelPath }) => {
464	    const impacts = [
465	      ...(Array.isArray(entry.impact) ? entry.impact : []),
466	      ...(Array.isArray(entry.keywords) ? entry.keywords : []),
467	    ];
468	    console.log(`[ConditionEngine] Component ${fileRelPath}:${entry.display_name || 'unknown'} asserts:`, impacts);
469	    impacts.forEach((imp) => {
470	      const clean = imp.trim();
471	      if (clean) activeConditionIds.add(clean);
472	    });
473	  });
474	
