483	        }
484	      });
485	    }
486	  });
487	
488	  // Detect Condition Collisions
489	  console.log('[ConditionEngine] Checking conflicts for active conditions:', Array.from(activeConditionIds).map((id) => conditions[id]?.display_name || id));
490	  const conditionConflicts: ConditionConflict[] = [];
491	  const processedConflictPairs = new Set<string>();
492	
493	  Array.from(activeConditionIds).forEach((condId) => {
494	    if (ignoredConditionIds.includes(condId)) return;
495	    const condA = conditions[condId];
496	    if (!condA || !Array.isArray(condA.conflicts_with)) return;
497	
498	    condA.conflicts_with.forEach((conflictingId) => {
499	      if (ignoredConditionIds.includes(conflictingId)) return;
500	      if (activeConditionIds.has(conflictingId)) {
501	        const pairKey = [condId, conflictingId].sort().join('::');
502	        if (!processedConflictPairs.has(pairKey)) {
503	          processedConflictPairs.add(pairKey);
504	          const condB = conditions[conflictingId];
505	          console.log('[ConditionEngine] Conflict detected:', condId, `(${condA.display_name || condId})`, '↔', conflictingId, `(${condB?.display_name || conflictingId})`);
