511	            resolved: false,
512	          });
513	        }
514	      }
515	    });
516	  });
517	
518	  // 5. Compile Master Prompt Chunked by Subfolder separated by "\nBREAK, \n"
519	  const folderBlocks: string[] = [];
520	  const seenTokens = new Set<string>();
521	
522	  for (const container of allFolderContainers) {
523	    const blockTokens: string[] = [];
524	
525	    // If container is a Matrix Domain, inject active Base Anchor Prompts first
526	    if (container.isMatrixDomain && container.domain) {
527	      const activeBaseIds = matrixBaseStates[container.domain.domainId] || [];
