530	        if (stateDef && stateDef.basePrompt) {
531	          const baseTokens = stateDef.basePrompt.split(',').map((t) => t.trim()).filter(Boolean);
532	          for (const token of baseTokens) {
533	            const clean = token.toLowerCase();
534	            if (!activeExclusionsSet.has(clean) && !seenTokens.has(clean)) {
535	              seenTokens.add(clean);
536	              blockTokens.push(token);
537	            }
538	          }
539	        }
540	      }
541	    }
542	
543	    // Collect active resolved tokens for each file in this folder container
544	    for (const file of container.files) {
545	      const resolvedKey = resolvedSelections[file.relPath];
546	      if (resolvedKey && file.entries[resolvedKey]) {
547	        const entry = file.entries[resolvedKey];
548	
549	        // Check if any required condition of this option is ignored
550	        const entryReqs = [
551	          ...(Array.isArray(entry.requirement) ? entry.requirement : []),
552	          ...(Array.isArray(entry.require) ? entry.require : []),
553	        ];
554	        const isBypassed = entryReqs.some((r) => ignoredConditionIds.includes(r.trim()));
555	        if (isBypassed) {
556	          // Bypassed because a required condition was ignored by the Manager
557	          continue;
558	        }
559	
560	        if (entry.prompt && entry.prompt.trim()) {
561	          const expandedPrompt = expandInlineChoices(entry.prompt);
562	          const tokens = expandedPrompt.split(',').map((t) => t.trim()).filter(Boolean);
563	          for (const token of tokens) {
564	            const clean = token.toLowerCase();
565	            if (!activeExclusionsSet.has(clean) && !seenTokens.has(clean)) {
566	              seenTokens.add(clean);
