568	            }
569	          }
570	        }
571	      }
572	    }
573	
574	    if (blockTokens.length > 0) {
575	      folderBlocks.push(blockTokens.join(', '));
576	    }
577	  }
578	
579	  const compiledPrompt = folderBlocks.join('\nBREAK, \n');
580	  const tokenCount = Math.round(
