75	
76	    async function readJson<T>(filename: string, fallback: T): Promise<T> {
77	      const filePath = normalizePath(`${DATA_FOLDER_PATH}/${filename}`);
78	      try {
79	        if (await adapter.exists(filePath)) {
80	          const raw = await adapter.read(filePath);
81	          return JSON.parse(raw);
82	        }
83	      } catch (err) {
84	        console.error(`[Hazard Trigger] Failed reading ${filename}, falling back to defaults:`, err);
85	      }
86	      return fallback;
87	    }
88	
89	    const categories = await readJson<Category[]>('categories.json', DEFAULT_CATEGORIES);
90	    const nodes = await readJson<PromptNode[]>('prompt_nodes.json', DEFAULT_NODES);
91	    const gachaPools = await readJson<GachaPool[]>('gacha_pools.json', DEFAULT_GACHA_POOLS);
92	    const wildcards = await readJson<WildcardRegistry>('wildcards.json', DEFAULT_WILDCARDS);
93	    const exclusions = await readJson<ExclusionConfig>('exclusions.json', DEFAULT_EXCLUSIONS);
94	    const presets = await readJson<Preset[]>('presets.json', DEFAULT_PRESETS);
95	
96	    return {
97	      categories,
98	      nodes,
99	      gachaPools,
100	      wildcards,
101	      exclusions,
102	      presets,
103	    };
104	  }
