106	  /**
107	   * Writes a specific JSON dataset to the vault data folder.
108	   */
109	  public static async saveFile<T>(app: App, filename: string, data: T): Promise<void> {
110	    const adapter = app.vault.adapter;
111	    const filePath = this.getPath(filename);
112	    const folderExists = await adapter.exists(DATA_FOLDER_PATH);
113	
114	    if (!folderExists) {
115	      await adapter.mkdir(DATA_FOLDER_PATH);
116	    }
117	
118	    await adapter.write(filePath, JSON.stringify(data, null, 2));
119	  }
120	}
