111	  /**
112	   * Recursively collects all JSON files under a directory.
113	   */
114	  private static async collectJsonFiles(app: App, dirPath: string): Promise<string[]> {
115	    const adapter = app.vault.adapter;
116	    const results: string[] = [];
117	
118	    try {
119	      if (!(await adapter.exists(dirPath))) return results;
120	      const listed = await adapter.list(dirPath);
121	
122	      for (const f of listed.files) {
123	        if (f.endsWith('.json') && !f.split('/').pop()?.startsWith('_')) {
124	          results.push(cleanPath(f));
125	        }
126	      }
127	
128	      for (const folder of listed.folders) {
129	        const subFiles = await this.collectJsonFiles(app, cleanPath(folder));
130	        results.push(...subFiles);
131	      }
132	    } catch (e) {
133	      console.warn(`[TemplateManager] Error scanning directory ${dirPath}:`, e);
134	    }
135	
136	    return results;
137	  }
